"""Current bilingual beta workflows; no controller or audio I/O."""

def en_update(chapters,help):
    by={ch['title']:ch for ch in chapters}
    def variant(micro,large,mk1=None):return dict(mikro=micro,mk2=large,mk1=mk1 or large)
    by['Welcome to Machinista']['intro']=by['Welcome to Machinista']['intro'].replace('WAV files','WAV and MP3 files')
    by['Know your controller']['intro']['mk1']='The full-size MK1 has two 256 x 64 pixel displays, eight display buttons, eight parameter encoders and separate VOLUME, SWING and TEMPO encoders. It has no large push encoder and no ENTER button. Use the labelled display actions to open, load or confirm a choice.'
    by['Know your controller']['notes'].append(('MK1 confirmation',variant('The encoder can also be pressed where ENTER is offered.','The large encoder can be pressed to confirm supported actions.','Encoder 1 selects utility items. OPEN, LOAD, OK or APPLY appears on display button 8 when confirmation is needed; use the displayed YES/CANCEL actions in a dialog. The three dedicated master encoders never become menu selectors.')))
    by['Setup and first start']['steps'][2]=variant('Open settings with SHIFT + MAIN. F1 selects AUDIO. Select INTERFACE and press ENTER.','Open settings with SHIFT + CONTROL. Display button 1 selects AUDIO. Encoder 1 selects the row; ENTER opens it. In INTERFACE, encoder 1 changes the device.','Open settings with SHIFT + CONTROL. Display button 1 selects AUDIO. Encoder 1 selects the row and display button 8 OPEN opens it. In INTERFACE, encoder 1 changes the device; button 4 BACK returns.')
    ch=by['Browse folders and load samples'];ch['intro']='Browse is a simple SD/USB folder tree containing your WAV and MP3 samples. Folders appear before files; turn the selection encoder to scroll through the list.'
    ch['steps']=[step.replace('WAV appears','WAV or MP3 appears') if isinstance(step,str) else step for step in ch['steps']]
    ch['notes'].append(('Quick Browse',variant('In BROWSE, SHIFT + F2 FIND locates the sample assigned to the current Sound.','In BROWSE, SHIFT + display button 2 FIND locates the sample assigned to the current Sound.')))
    by['Play, locate and set tempo']['notes'][0]=('Tempo',variant('MAIN opens the Volume/Swing/Tempo panel; F3 selects TEMPO. SHIFT gives fine changes to two decimal places. SHIFT + ENTER is tap tempo.','TEMPO selects its persistent panel. Turn the master encoder; SHIFT gives fine changes. Tap with SHIFT + NOTE REPEAT. VOLUME and SWING have their own panels.','Turn the dedicated TEMPO encoder; SHIFT gives fine changes to two decimal places. Tap with SHIFT + NOTE REPEAT. VOLUME and SWING are separate dedicated encoders.'))
    by['Mute, solo, selection and duplication']['notes'].append(('Held-mode actions',variant('MAIN plus a held mode changes its PIN preference. The three display actions remain context-dependent.','When a matching mode is held, display button 1 reads PIN. In SCENE, MUTE/SOLO, DUPLICATE and GRID, the displaced first action is on display button 4. Once you leave that mode, the first action belongs to the new screen.')))
    ch=by['Audio and controller settings'];ch['intro']=variant('SHIFT + MAIN opens AUDIO, MIDI and SYSTEM. Choose a folder, select a row and press ENTER.','SHIFT + CONTROL opens AUDIO, MIDI and SYSTEM. Select a row with encoder 1 and press ENTER. Device choice, Main/Cue and Cue Level use encoder 1.','SHIFT + CONTROL opens AUDIO, MIDI and SYSTEM. Select a row with encoder 1 and use display button 8 OPEN. Device choice, Main/Cue and Cue Level use encoder 1; button 4 BACK goes to the parent folder.')
    ch['notes'].append(('Hardware mixer and reset',variant('AUDIO > INTERFACE MIXER exposes the controls reported by ALSA, including capture gains and output/headphone levels where supported. Pads remain playable in settings. SHIFT + F1 resets supported display/pad preferences.','AUDIO > INTERFACE MIXER shows hardware controls reported by ALSA; pads remain playable while adjusting levels. Display/Pad pages offer button 2 RESET for this controller only. DAC level pages include headphone/speaker MUTE buttons.')))
    by['Automation, macros and MIDI Learn']['steps'][3]='For MIDI Learn, touch the target parameter, open MIDI LEARN, press LEARN (F2 / display button 2), then send the external CC. BACK cancels; REMOVE deletes the selected mapping. Test with automation writing off.'
    # The remaining current workflows are separate pages to preserve readable type.
    extras=[
      dict(title='Live FX performance and recording',screens=['LIVE FX'],intro='Live FX is a built-in performance processor. It remains available without installing any LV2 plugins. It processes the live mix; ordinary sampler and plugin controls remain separate.',steps=[variant('Hold SHIFT and press SOLO to open Live FX.','Hold NAVIGATE and use display button 7 LIVE FX. In waveform navigation use button 3. SHIFT + SOLO is an additional shortcut.'),'Pads 1-15 select effects; pad 16 is DRY/OFF. PUNCH is momentary, FLEX retains the effect after release and KNOB toggles a selected effect. Read the effect name before playing.',variant('F1/F2/F3 choose PUNCH/FLEX/KNOB. Turn the encoder for DEPTH.','Display buttons 1-3 choose PUNCH/FLEX/KNOB. Encoder 1 changes DEPTH; buttons 5/6 decrease/increase it. Button 7 is OFF.'),'Enable PLAY and REC to capture FX gestures into Pattern automation. With REC off, playing effects does not write notes or automation.'],notes=[('Leave effects safely','BACK, SHIFT + SOLO or normal workspace navigation turns off the manually held/latched effect. New/Load also clears manual FX. Saved automation can activate its recorded effect during playback.'),('Playback first','Complex plugin chains and high voice counts still consume CPU. A built-in effect does not make an overloaded instrument chain safe.')]),
      dict(title='Scene tools, banks and quantize',screens=['SCENE OPTIONS','OPTIONS'],intro='Scene Options distinguishes automatic Scene length, independent Pattern copies and removal of a complete Scene. These operations are different from clearing its clips.',steps=[variant('Hold SCENE, then SHIFT + F1 OPTIONS. Turn the encoder to choose an operation and use F2 SELECT.','Hold SCENE, then SHIFT + display button 4 OPTIONS. Encoder 1 selects the operation; display button 2 SELECT opens it.'),'AUTO LENGTH removes a manual Scene-length override. UNIQUE PATTERNS copies referenced Patterns so that edits no longer change another Scene using the original Patterns. DELETE SCENE removes the Scene and its Song references after confirmation.',variant('SCENE or PATTERN + SHIFT + navigation arrows changes banks.','SCENE or PATTERN + SHIFT + PAGE LEFT/RIGHT changes banks. SCENE also offers BANK-/BANK+ on buttons 7/8.'),variant('Hold GRID, choose QUANT with F1, set the target and strength, then press ENTER to apply.','Hold GRID, choose QUANT with button 4, set target/strength and use button 8 APPLY.')],notes=[('Check the target','Use a disposable project copy when learning Delete, Clear or Unique. The destination and confirmation question matter.')]),
      dict(title='Custom chords and playing variations',screens=['PAD CONFIG'],intro='Keyboard/Chord performance plays the currently selected Sound: its sampler Zones or its loaded LV2 instrument. It does not select a different Sound for each key.',steps=['Open PAD MODE, enable KEYBOARD and choose CUSTOM chord mode. Use the chord configuration pages to select a preset or edit the pad assignments.','Import supported MPC .progression or Ripchord chord presets in the WebUI. Chord maps are note assignments, not MPC sample-based Keygroup instruments.','Use LEARN to capture incoming notes into a selected chord slot, or add/remove voices in its editor. Save the chord preset when finished.','Adjust strum/delayed attacks and playing variations in the chord configuration. Test with REC off, then record the resulting performance into a Pattern.'],notes=[('Pad feedback','Assigned chord pads are dim. A played pad flashes bright; the last played pad stays highlighted so you retain your editing focus.'),('Sound mapping','Sampler Zones need correct Root, Key Low/High and Velocity ranges. An imported chord map supplies no instrument sound or samples.')]),
      dict(title='Sounds, Zones and Autosampler',screens=['ZONE','AUTOSAMPLER'],intro='A Sound can contain a multisample sampler instrument or a live LV2 instrument with its plugin strip and saved state. Sampling a plugin produces WAV Zones; saving its patch keeps it as a live plugin.',steps=['In the WebUI Sounds area, add samples, review Root and Key Low/High as note names, then set velocity ranges. Note names in filenames can suggest Root; review every inferred value before saving.','Name the Sound and choose a folder/tags. Sounds appear in their own Browser category. Controller Zone editing remains available.','For Autosampler, stop transport/recording. Choose External MIDI or the currently loaded LV2 instrument. External hardware needs both MIDI OUT and audio IN connections.',variant('In SAMPLING hold NAV, select AUTO and release. Arrows choose fields and the encoder edits them. F2 START begins; F3 CANCEL stops.','In SAMPLING use the page arrows to reach AUTO. Encoders configure note range, interval, velocity layers, note length, tail and gap. NAME/FOLDER use the name editor; START/CANCEL are labelled actions.'),'Choose the name, note range and source carefully, then START. When complete, the recorded Zones are mapped automatically and saved as a Sound.'],notes=[('No factory assets','This image contains no Sound presets, samples or LV2 bundles. Add your own files and install compatible plugins separately.'),('Live LV2 patch','Save current Sound / LV2 patch stores settings/state and the strip, not a rendered sample. The same compatible plugin must be installed to load it later.')]),
      dict(title='WebUI files, plugins and power',screens=['SETTINGS'],intro='Open http://machinista.local:8080 on the local network, or http://10.42.0.1:8080 while connected to the Machinista-XXXX hotspot. Its password is machinista.',steps=['In Sample Library, open a destination folder and upload WAV/MP3. Create folders, move files/folders and use recoverable deletion to organize your library.','Use the Projects area to download/upload project packages. Collect referenced samples for a portable backup, and keep required plugin installers separately.','In LV2, upload a compiled ARM64 Linux bundle as ZIP/TAR. The device checks architecture, dependencies and metadata. Compatible uploads activate when transport and recording are stopped.','The installed-plugin list shows available bundles and removal actions. Removing a plugin does not replace it in saved Sounds/projects; reinstall it before those can play correctly.','System provides SSH enable/disable, restart and shutdown. Select a home Wi-Fi router and enter its password in Network; loss of the saved connection returns to the hotspot.'],notes=[('Power and updates','Shut down before unplugging the Pi or a HAT. This public beta contains no automatic updater; updates use a newly supplied image.'),('Own JV ROMs','The optional JV emulator is supplied separately, without ROMs. Install its LV2 archive, then configure your own ROMs/expansion files in the optional JV WebUI section. No sounds are supplied by the core image.')])
    ]
    chapters.extend(extras)
    help.update({'LIVE FX':'Pads 1-15 play effects; pad 16 is OFF. Choose PUNCH/FLEX/KNOB and DEPTH. REC enables FX automation capture.','SCENE OPTIONS':'Select Auto Length, Unique Patterns or confirmed Delete. BACK returns to SCENE.'})


def de_update(chapters,source,help):
    by={ch['title']:chapters[i] for i,ch in enumerate(source[:len(chapters)])}
    def variant(micro,large,mk1=None):return dict(mikro=micro,mk2=large,mk1=mk1 or large)
    by['Welcome to Machinista']['intro']=by['Welcome to Machinista']['intro'].replace('WAV-Dateien','WAV- und MP3-Dateien')
    ch=by['Know your controller'];ch['intro']['mk1']='Die große MK1 hat zwei Displays mit 256 x 64 Pixeln, acht Displaytasten, acht Parameterregler und getrennte Regler für VOLUME, SWING und TEMPO. Sie besitzt keinen großen drückbaren Encoder und keine ENTER-Taste. Nutze die beschrifteten Displayaktionen zum Öffnen, Laden oder Bestätigen.'
    ch['notes'].append(('Bestätigen auf der MK1',variant('Wo ENTER angeboten wird, kann häufig auch der Encoder gedrückt werden.','Der große Encoder bestätigt unterstützte Aktionen durch Drücken.','Encoder 1 wählt Menüeinträge. OPEN, LOAD, OK oder APPLY erscheint bei Bedarf auf Displaytaste 8; Dialoge haben YES/CANCEL. Die drei Master-Regler sind keine Menüauswahl.')))
    by['Setup and first start']['steps'][2]=variant('Öffne Einstellungen mit SHIFT + MAIN. F1 wählt AUDIO. Wähle INTERFACE und drücke ENTER.','Öffne Einstellungen mit SHIFT + CONTROL. Displaytaste 1 wählt AUDIO. Encoder 1 wählt die Zeile, ENTER öffnet sie. In INTERFACE ändert Encoder 1 das Gerät.','SHIFT + CONTROL öffnet Einstellungen. Taste 1 wählt AUDIO, Encoder 1 die Zeile, Taste 8 OPEN öffnet sie. In INTERFACE wählt Encoder 1 das Gerät; Taste 4 BACK führt zurück.')
    ch=by['Browse folders and load samples'];ch['intro']='Browse zeigt eine einfache SD-/USB-Ordnerstruktur mit WAV- und MP3-Samples. Ordner stehen vor Dateien; drehe den Auswahlregler, um durch die Liste zu gehen.'
    ch['steps']=[step.replace('WAV-Datei','WAV- oder MP3-Datei') if isinstance(step,str) else step for step in ch['steps']]
    ch['notes'].append(('Quick Browse',variant('In BROWSE führt SHIFT + F2 FIND zum Sample des aktuellen Sounds.','In BROWSE führt SHIFT + Displaytaste 2 FIND zum Sample des aktuellen Sounds.')))
    by['Play, locate and set tempo']['notes'][0]=('Tempo',variant('MAIN öffnet Volume/Swing/Tempo; F3 wählt TEMPO. SHIFT ermöglicht feine Änderungen mit zwei Nachkommastellen. SHIFT + ENTER ist Tap Tempo.','TEMPO wählt seine dauerhafte Anzeige. Drehe den Master-Encoder; SHIFT erlaubt feine Änderungen. Tippe das Tempo mit SHIFT + NOTE REPEAT. VOLUME und SWING haben eigene Anzeigen.','Drehe den eigenen TEMPO-Regler; SHIFT erlaubt feine Änderungen mit zwei Nachkommastellen. Tippe das Tempo mit SHIFT + NOTE REPEAT. VOLUME und SWING sind eigene Regler.'))
    by['Mute, solo, selection and duplication']['notes'].append(('Aktionen beim Halten',variant('MAIN plus gehaltene Modustaste ändert deren PIN-Zustand. Die drei Displayaktionen richten sich nach dem Kontext.','Beim Halten des passenden Modus zeigt Displaytaste 1 PIN. In SCENE, MUTE/SOLO, DUPLICATE und GRID liegt die verdrängte erste Aktion auf Displaytaste 4. Nach einem Ansichtswechsel gehört die erste Taste zur neuen Anzeige.')))
    ch=by['Audio and controller settings'];ch['intro']=variant('SHIFT + MAIN öffnet AUDIO, MIDI und SYSTEM. Wähle einen Ordner, markiere eine Zeile und drücke ENTER.','SHIFT + CONTROL öffnet AUDIO, MIDI und SYSTEM. Encoder 1 wählt eine Zeile, ENTER öffnet sie. Interface, Main/Cue und Cue Level werden mit Encoder 1 eingestellt.','SHIFT + CONTROL öffnet AUDIO, MIDI und SYSTEM. Encoder 1 wählt Einträge und Werte; Taste 8 OPEN öffnet Menüs, Taste 4 BACK führt zurück.')
    ch['notes'].append(('Hardware-Mixer und Reset',variant('AUDIO > INTERFACE MIXER zeigt von ALSA gemeldete Aufnahme-, Ausgangs- und Kopfhörerpegel, soweit das Gerät diese anbietet. Pads bleiben spielbar. SHIFT + F1 setzt unterstützte Display-/Pad-Werte zurück.','AUDIO > INTERFACE MIXER zeigt die von ALSA gemeldeten Hardware-Regler; Pads bleiben beim Einstellen spielbar. Display-/Pad-Seiten haben Taste 2 RESET nur für diesen Controller. DAC-Pegelseiten bieten MUTE für Kopfhörer/Lautsprecher.')))
    by['Automation, macros and MIDI Learn']['steps'][3]='Berühre für MIDI Learn den Zielparameter, öffne MIDI LEARN und drücke LEARN (F2 / Displaytaste 2). Sende dann den externen CC. BACK bricht ab, REMOVE löscht die gewählte Zuordnung. Teste ohne Automation-Aufnahme.'
    extras=[
      dict(title='Live FX spielen und aufnehmen',intro='Live FX ist ein eingebauter Performance-Prozessor und funktioniert ohne installierte LV2-Plug-ins. Er bearbeitet die Live-Mischung; Sampler- und Plug-in-Regler bleiben getrennt.',steps=[variant('Halte SHIFT und drücke SOLO, um Live FX zu öffnen.','Halte NAVIGATE und nutze Displaytaste 7 LIVE FX. Bei Wellenform-Navigation ist es Taste 3. SHIFT + SOLO ist ein weiterer Zugang.'),'Pads 1-15 wählen Effekte; Pad 16 ist DRY/OFF. PUNCH wirkt beim Halten, FLEX bleibt nach dem Loslassen aktiv, KNOB schaltet den gewählten Effekt um. Lies vor dem Spielen den Effektnamen.',variant('F1/F2/F3 wählen PUNCH/FLEX/KNOB. Drehe den Encoder für DEPTH.','Displaytasten 1-3 wählen PUNCH/FLEX/KNOB. Encoder 1 ändert DEPTH, Tasten 5/6 verringern/erhöhen den Wert. Taste 7 ist OFF.'),'Aktiviere PLAY und REC, um FX-Gesten als Pattern-Automation aufzunehmen. Bei ausgeschaltetem REC werden weder Noten noch Automation geschrieben.'],notes=[('Effekte sicher verlassen','BACK, SHIFT + SOLO oder normale Navigation schaltet den manuell gehaltenen/festgesetzten Effekt aus. Auch New/Load setzt manuelle FX zurück. Gespeicherte Automation kann ihren Effekt bei Wiedergabe erneut aktivieren.'),('Wiedergabe zuerst','Komplexe Plug-in-Ketten und viele Stimmen benötigen weiterhin CPU. Ein eingebauter Effekt beseitigt keine Überlastung einer Instrumentenkette.')]),
      dict(title='Scene-Werkzeuge, Bänke und Quantize',intro='Scene Options trennt automatische Scene-Länge, unabhängige Pattern-Kopien und das Entfernen einer ganzen Scene. Diese Aktionen unterscheiden sich vom Leeren ihrer Clips.',steps=[variant('Halte SCENE und drücke SHIFT + F1 OPTIONS. Drehe den Encoder für die Aktion und nutze F2 SELECT.','Halte SCENE und drücke SHIFT + Displaytaste 4 OPTIONS. Encoder 1 wählt die Aktion, Displaytaste 2 SELECT öffnet sie.'),'AUTO LENGTH entfernt eine manuelle Scene-Länge. UNIQUE PATTERNS kopiert referenzierte Patterns, damit Änderungen andere Scenes mit den ursprünglichen Patterns nicht verändern. DELETE SCENE entfernt nach Bestätigung auch ihre Song-Verweise.',variant('SCENE oder PATTERN + SHIFT + Navigationspfeile wechselt Bänke.','SCENE oder PATTERN + SHIFT + PAGE LEFT/RIGHT wechselt Bänke. SCENE bietet zusätzlich BANK-/BANK+ auf Tasten 7/8.'),variant('Halte GRID, wähle QUANT mit F1, stelle Ziel und Stärke ein und drücke ENTER.','Halte GRID, wähle QUANT mit Taste 4, stelle Ziel und Stärke ein und nutze Taste 8 APPLY.')],notes=[('Ziel prüfen','Übe Delete, Clear oder Unique an einer Projektkopie. Ziel und Bestätigungsfrage sind entscheidend.')]),
      dict(title='Eigene Akkorde und Spielvariationen',intro='Keyboard/Chord spielt den aktuell gewählten Sound mit seinen Sampler-Zones oder dem geladenen LV2-Instrument. Die Tasten wählen dabei nicht jeweils einen anderen Sound.',steps=['Öffne PAD MODE, aktiviere KEYBOARD und wähle den Akkordmodus CUSTOM. Auf den Akkordseiten kannst du ein Preset wählen oder Pad-Zuordnungen bearbeiten.','Importiere unterstützte MPC-.progression- oder Ripchord-Akkordpresets in der WebUI. Diese enthalten Notenzuordnungen, keine samplebasierten MPC-Keygroup-Instrumente.','LEARN erfasst eingehende Noten im gewählten Akkord-Slot. Im Editor lassen sich Stimmen hinzufügen/entfernen. Speichere anschließend das Akkordpreset.','Stelle Strum/versetzte Anschläge und Spielvariationen in der Akkordkonfiguration ein. Teste ohne REC und nimm die Performance anschließend in ein Pattern auf.'],notes=[('Pad-Rückmeldung','Belegte Akkordpads leuchten schwach, gespielte hell. Das zuletzt gespielte Pad bleibt hervorgehoben, damit der Bearbeitungsfokus erkennbar bleibt.'),('Sound-Zuordnung','Sampler-Zones benötigen passende Root-, Key-Low/High- und Velocity-Bereiche. Ein Akkordpreset enthält weder Instrumentenklang noch Samples.')]),
      dict(title='Sounds, Zones und Autosampler',intro='Ein Sound kann ein Multisample-Instrument oder ein live gespieltes LV2-Instrument mit Plug-in-Kette und gespeichertem Zustand sein. Sampling erzeugt WAV-Zones; Patch-Speichern erhält das Live-Plug-in.',steps=['Füge in der WebUI unter Sounds Samples hinzu und prüfe Root sowie Key Low/High als Notennamen. Lege Velocity-Bereiche fest. Notennamen im Dateinamen können Root vorschlagen; prüfe jeden Vorschlag vor dem Speichern.','Benenne den Sound und wähle Ordner/Tags. Sounds erscheinen als eigene Browser-Kategorie. Die Zone-Bearbeitung am Controller bleibt erhalten.','Stoppe Transport/Aufnahme für Autosampler. Wähle External MIDI oder das geladene LV2-Instrument. Externe Hardware benötigt MIDI OUT und eine Audio-IN-Verbindung.',variant('Halte in SAMPLING NAV, wähle AUTO und lasse los. Pfeile wählen Felder, der Encoder ändert Werte. F2 START startet, F3 CANCEL bricht ab.','Wechsle in SAMPLING mit den Seitenpfeilen zu AUTO. Die Encoder stellen Notenbereich, Intervall, Velocity-Layer, Notenlänge, Tail und Gap ein. NAME/FOLDER öffnen den Namenseditor; START/CANCEL sind beschriftet.'),'Prüfe Name, Notenbereich und Quelle und nutze START. Nach Abschluss werden die aufgenommenen Zones automatisch zugeordnet und als Sound gespeichert.'],notes=[('Keine Werksinhalte','Das Image enthält keine Sound-Presets, Samples oder LV2-Bundles. Füge eigene Dateien hinzu und installiere kompatible Plug-ins separat.'),('Live-LV2-Patch','Save current Sound / LV2 patch speichert Einstellungen/Zustand und Kette statt gerendertem Audio. Zum späteren Laden muss dasselbe kompatible Plug-in installiert sein.')]),
      dict(title='WebUI: Dateien, Plug-ins und Ausschalten',intro='Öffne im lokalen Netz http://machinista.local:8080 oder im Machinista-XXXX-Hotspot http://10.42.0.1:8080. Sein Passwort ist machinista.',steps=['Öffne in Sample Library einen Zielordner und lade WAV/MP3 hoch. Lege Ordner an, verschiebe Dateien/Ordner und nutze das wiederherstellbare Löschen zum Aufräumen.','Unter Projects lassen sich Projektpakete herunterladen/hochladen. Sammle referenzierte Samples für ein portables Backup und bewahre benötigte Plug-in-Installer getrennt auf.','Lade unter LV2 ein kompiliertes ARM64-Linux-Bundle als ZIP/TAR hoch. Das Gerät prüft Architektur, Bibliotheken und Metadaten. Kompatible Uploads werden bei gestopptem Transport/Aufnahme aktiviert.','Die Plug-in-Liste zeigt installierte Bundles und Löschaktionen. Entfernen ersetzt kein Plug-in in gespeicherten Sounds/Projekten; installiere es vor deren Wiedergabe erneut.','System bietet SSH ein/aus, Neustart und Herunterfahren. Wähle unter Network deinen WLAN-Router und sein Passwort; fällt dessen Verbindung weg, kehrt der Pi zum Hotspot zurück.'],notes=[('Ausschalten und Updates','Fahre vor dem Trennen von Strom oder HAT herunter. Diese öffentliche Beta enthält keinen automatischen Updater; Updates erfolgen mit einem neu bereitgestellten Image.'),('Eigene JV-ROMs','Der optionale JV-Emulator wird separat ohne ROMs geliefert. Installiere sein LV2-Archiv und richte eigene ROMs/Expansion-Dateien im optionalen JV-Bereich der WebUI ein. Das Basisimage enthält keine Klänge.')])
    ]
    chapters.extend(extras)
    help.update({'LIVE FX':'Pads 1-15 spielen Effekte, Pad 16 ist OFF. Wähle PUNCH/FLEX/KNOB und DEPTH. REC aktiviert die Aufzeichnung der FX-Gesten.','SCENE OPTIONS':'Wähle Auto Length, Unique Patterns oder bestätigtes Delete. BACK führt zu SCENE.'})
